    [Fact]
    public async Task Recovery_ReturnsMoreThanChannelCapacity_WithoutBlockingStartup()
    {
        var services = new ServiceCollection();
        var databaseName = Guid.NewGuid().ToString();
        services.AddDbContext<AppDbContext>(options => options.UseInMemoryDatabase(databaseName));
        using var provider = services.BuildServiceProvider();
        await using (var scope = provider.CreateAsyncScope())
        {
            var dbContext = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            var user = new UserAccount { Email = "synthetic-recovery@example.invalid", PasswordHash = "synthetic", DisplayName = "Synthetic User", UserType = UserType.FamilyUser };
            var family = new Family { Name = "Synthetic Recovery Family", CreatedByUser = user };
            var member = new Member { Family = family, User = user, DisplayName = "Synthetic Member", DateOfBirth = new DateOnly(1990, 1, 1), Role = FamilyRole.Head };
            for (var index = 0; index < 101; index++)
            {
                var episode = new Episode { Member = member, SymptomsJson = "[]", DurationDays = 1, Severity = 1 };
                dbContext.TriageCases.Add(new TriageCase { Episode = episode, Member = member, Status = TriageStatus.Submitted });
            }
            await dbContext.SaveChangesAsync();
        }

        var worker = new TriageWorker(new TriageWorkQueue(), provider.GetRequiredService<IServiceScopeFactory>(), NullLogger<TriageWorker>.Instance);
        var recovered = await worker.RecoverInterruptedCasesAsync(CancellationToken.None).WaitAsync(TimeSpan.FromSeconds(2));

        recovered.Should().HaveCount(101);
        await using var verificationScope = provider.CreateAsyncScope();
        var statuses = await verificationScope.ServiceProvider.GetRequiredService<AppDbContext>().TriageCases.Select(x => x.Status).ToListAsync();
        statuses.Should().OnlyContain(status => status == TriageStatus.Submitted);
    }
    [Theory]
    [InlineData(TriageStatus.Planning, true)]
    [InlineData(TriageStatus.ContextReady, false)]
    [InlineData(TriageStatus.Analysed, true)]
    [InlineData(TriageStatus.RiskAssessed, true)]
    [InlineData(TriageStatus.Validated, true)]
    public async Task Recovery_InterruptedPipelineFailsSafe_PreservingSubmittedInput(TriageStatus status, bool traced)
    {
        var services = new ServiceCollection();
        var name = Guid.NewGuid().ToString();
        services.AddDbContext<AppDbContext>(options => options.UseInMemoryDatabase(name));
        using var provider = services.BuildServiceProvider();
        Guid id;
        await using (var scope = provider.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            var item = SyntheticCase(status);
            item.DraftAdvisoryJson = "{\"syntheticDraft\":true}";
            if (traced) item.Traces.Add(Trace(item.Id));
            db.Add(item);
            await db.SaveChangesAsync();
            id = item.Id;
        }
        var worker = new TriageWorker(new TriageWorkQueue(), provider.GetRequiredService<IServiceScopeFactory>(), NullLogger<TriageWorker>.Instance);
        (await worker.RecoverInterruptedCasesAsync(default)).Should().BeEmpty();
        await using var verifyScope = provider.CreateAsyncScope();
        var persisted = await verifyScope.ServiceProvider.GetRequiredService<AppDbContext>().TriageCases.Include(x => x.Episode).SingleAsync(x => x.Id == id);
        persisted.Status.Should().Be(TriageStatus.FailedSafe);
        persisted.FailureCode.Should().Be("PROCESS_INTERRUPTED");
        persisted.DraftAdvisoryJson.Should().BeNull();
        persisted.Episode!.SymptomsJson.Should().Be("[\"synthetic symptom\"]");
        persisted.Episode.Notes.Should().Be("Synthetic original context");
    }

    [Theory]
    [InlineData(TriageStatus.PendingDoctorReview)]
    [InlineData(TriageStatus.LowConfidence)]
    [InlineData(TriageStatus.Approved)]
    [InlineData(TriageStatus.Escalated)]
    [InlineData(TriageStatus.FailedSafe)]
    [InlineData(TriageStatus.Withdrawn)]
    [InlineData(TriageStatus.Superseded)]
    public async Task Recovery_DoesNotChangeNonProcessingCase(TriageStatus status)
    {
        var services = new ServiceCollection();
        services.AddDbContext<AppDbContext>(options => options.UseInMemoryDatabase($"synthetic-recovery-{status}-{GetHashCode()}"));
        using var provider = services.BuildServiceProvider();
        await using (var scope = provider.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            var item = SyntheticCase(status);
            item.FailureCode = "SYNTHETIC_EXISTING";
            item.DraftAdvisoryJson = "synthetic unchanged draft";
            db.Add(item);
            await db.SaveChangesAsync();
        }
        var worker = new TriageWorker(new TriageWorkQueue(), provider.GetRequiredService<IServiceScopeFactory>(), NullLogger<TriageWorker>.Instance);
        (await worker.RecoverInterruptedCasesAsync(default)).Should().BeEmpty();
        await using var verifyScope = provider.CreateAsyncScope();
        var persisted = await verifyScope.ServiceProvider.GetRequiredService<AppDbContext>().TriageCases.SingleAsync();
        persisted.Status.Should().Be(status);
        persisted.FailureCode.Should().Be("SYNTHETIC_EXISTING");
        persisted.DraftAdvisoryJson.Should().Be("synthetic unchanged draft");
    }

    [Fact]
    public async Task Recovery_RechecksTraceCreatedAfterInitialScan()
    {
        var name = Guid.NewGuid().ToString();
        var root = new InMemoryDatabaseRoot();
        var baselineOptions = new DbContextOptionsBuilder<AppDbContext>().UseInMemoryDatabase(name, root).Options;
        Guid id;
        await using (var seed = new AppDbContext(baselineOptions))
        {
            var item = SyntheticCase(TriageStatus.Planning);
            seed.Add(item);
            await seed.SaveChangesAsync();
            id = item.Id;
        }
        var interceptor = new BeforeReloadQuery(() =>
        {
            // Simulate another process committing its first trace after the startup scan.
            using var other = new AppDbContext(baselineOptions);
            other.AgentTraces.Add(Trace(id));
            other.SaveChanges();
        });
        var services = new ServiceCollection();
        services.AddDbContext<AppDbContext>(options => options.UseInMemoryDatabase(name, root).EnableServiceProviderCaching(false).AddInterceptors(interceptor));
        using var provider = services.BuildServiceProvider();
        var worker = new TriageWorker(new TriageWorkQueue(), provider.GetRequiredService<IServiceScopeFactory>(), NullLogger<TriageWorker>.Instance);
        (await worker.RecoverInterruptedCasesAsync(default)).Should().BeEmpty();
        interceptor.Injected.Should().BeTrue();
        await using var verify = new AppDbContext(baselineOptions);
        var persisted = await verify.TriageCases.SingleAsync();
        persisted.Status.Should().Be(TriageStatus.FailedSafe);
        persisted.FailureCode.Should().Be("PROCESS_INTERRUPTED");
    }

    [Fact]
    public async Task UnexpectedProviderCancellation_StillMarksWorkerFailure()
    {
        var services = new ServiceCollection();
        var name = Guid.NewGuid().ToString();
        services.AddDbContext<AppDbContext>(options => options.UseInMemoryDatabase(name));
        services.AddScoped<ITriageOrchestrator, UnexpectedCancellation>();
        using var provider = services.BuildServiceProvider();
        await using (var scope = provider.CreateAsyncScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
            db.Add(SyntheticCase(TriageStatus.Submitted));
            await db.SaveChangesAsync();
        }
        var queue = new IdleSignalQueue();
        using var worker = new TriageWorker(queue, provider.GetRequiredService<IServiceScopeFactory>(), NullLogger<TriageWorker>.Instance);
        await worker.StartAsync(default);
        try { await queue.ReachedIdle.Task.WaitAsync(TimeSpan.FromSeconds(2)); }
        finally { await worker.StopAsync(default); }
        await using var verifyScope = provider.CreateAsyncScope();
        var persisted = await verifyScope.ServiceProvider.GetRequiredService<AppDbContext>().TriageCases.SingleAsync();
        persisted.Status.Should().Be(TriageStatus.FailedSafe);
        persisted.FailureCode.Should().Be("WORKER_FAILURE");
        persisted.DraftAdvisoryJson.Should().BeNull();
    }

    private sealed class UnexpectedCancellation : ITriageOrchestrator
    {
        public Task RunAsync(Guid caseId, CancellationToken cancellationToken) => throw new OperationCanceledException("Synthetic provider cancellation without host shutdown");
    }
    private sealed class IdleSignalQueue : ITriageWorkQueue
    {
        public TaskCompletionSource ReachedIdle { get; } = new(TaskCreationOptions.RunContinuationsAsynchronously);
        public ValueTask QueueAsync(Guid caseId, CancellationToken cancellationToken) => throw new NotSupportedException();
        public async ValueTask<Guid> DequeueAsync(CancellationToken cancellationToken)
        {
            ReachedIdle.TrySetResult();
            await Task.Delay(Timeout.Infinite, cancellationToken);
            throw new InvalidOperationException("Synthetic idle queue should only exit through shutdown");
        }
    }

    private sealed class BeforeReloadQuery(Action inject) : IQueryExpressionInterceptor
    {
        private int queries;
        public bool Injected { get; private set; }
        public Expression QueryCompilationStarting(Expression queryExpression, QueryExpressionEventData eventData)
        {
            if (++queries == 2) { inject(); Injected = true; }
            return queryExpression;
        }
    }
    private static AgentTrace Trace(Guid id) => new()
    {
        TriageCaseId = id, Agent = AgentKind.Coordinator, StepNumber = 0,
        InputHash = "synthetic", ToolsRequestedJson = "[]", ToolsAllowedJson = "[]", ToolsDeniedJson = "[]"
    };
    private static TriageCase SyntheticCase(TriageStatus status)
    {
        var user = new UserAccount { Email = "synthetic-interrupted@example.invalid", PasswordHash = "synthetic", DisplayName = "Synthetic User", UserType = UserType.FamilyUser };
        var family = new Family { Name = "Synthetic Recovery Family", CreatedByUser = user };
        var member = new Member { Family = family, User = user, DisplayName = "Synthetic Member", DateOfBirth = new(1990, 1, 1), Role = FamilyRole.Head };
        var episode = new Episode { Member = member, SymptomsJson = "[\"synthetic symptom\"]", DurationDays = 2, Severity = 3, Notes = "Synthetic original context" };
        return new TriageCase { Episode = episode, Member = member, Status = status };
    }

}
